import{_ as t,o as e,c as o,a2 as i}from"./chunks/framework.F7eQ-ohH.js";const r="/bzygq/assets/8d7f08e6eb604eaab1512aa9839c1705.Ci4awq1A.png",l="/bzygq/assets/597e7dfc4531416689d218d8654bd4ef.Dnhd_McR.png",n="/bzygq/assets/6e60ee282c854b899d795419ddab8cc8.DOCvWL1-.png",s="/bzygq/assets/4bc0a674cefb4a808fc5f88aa99b8494.w0CsGkOn.png",p="/bzygq/assets/4786a567594844099b9b1b1645fd5518.B1DG3OEP.png",c="/bzygq/assets/a0fc1500c43e4d3298bd567b15275f73.sbCPrFYI.png",d="/bzygq/assets/484fd591f46f436eaa041573605ad35d.B5XvQWjR.png",h="/bzygq/assets/2ac155ba1e5f44f1a74697a171508557.NvojIpw4.png",g="/bzygq/assets/169a8f522dc04963aab631565b2c7403.BYDkfR1B.png",u="/bzygq/assets/7da200eed519471c81c74e25c3b0d301.CIJnB6wz.png",v="/bzygq/assets/597e7dfc4531416689d218d8654bd4ef.Dnhd_McR.png",m="/bzygq/assets/b9b08b2187694c4f95f2f0ce82a0049f.DmOCLnG2.png",S=JSON.parse('{"title":"三、Java运行时数据区","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/Java虚拟机/三、Java运行时数据区.md","filePath":"Java面试问题汇总/Java虚拟机/三、Java运行时数据区.md","lastUpdated":1788929995000}'),J={name:"Java面试问题汇总/Java虚拟机/三、Java运行时数据区.md"};function b(M,a,f,q,O,k){return e(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="三、java运行时数据区" tabindex="-1">三、Java运行时数据区 <a class="header-anchor" href="#三、java运行时数据区" aria-label="Permalink to &quot;三、Java运行时数据区&quot;">​</a></h1><h2 id="java运行时数据区概述" tabindex="-1">Java运行时数据区概述 <a class="header-anchor" href="#java运行时数据区概述" aria-label="Permalink to &quot;Java运行时数据区概述&quot;">​</a></h2><p><img src="'+r+'" alt="images/ESJHbmq6roPrkCxBmuUcR9cknuf.png"></p><p>images/ESJHbmq6roPrkCxBmuUcR9cknuf.png</p><p>Java运行时数据区（也称为Java内存模型或JVM内存结构）是Java虚拟机（JVM）在执行Java程序时使用的内存布局。它被划分为几个不同的部分，每个部分都有其特定的用途和生命周期。以下是Java运行时数据区的主要组成部分：</p><ol><li><strong>堆（Heap）</strong>： 这是Java程序中所有类实例和数组对象的存储区域。堆是由垃圾收集器管理的，用于动态分配内存。所有的线程共享这个堆空间。堆被进一步细分为新生代（Young Generation）、老年代（Old Generation）和永久代/元空间（PermGen/Metaspace）。新生代又可以分为Eden空间和两个Survivor空间。</li><li><strong>方法区（Method Area）</strong>： 方法区是所有线程共享的内存区域，用来存储已被虚拟机加载的类信息、常量、静态变量、即时编译器编译后的代码等数据。在HotSpot JVM中，方法区有时被称为“永久代”（PermGen），但在Java 8及以后版本中，已经被“元空间”（Metaspace）取代，后者使用本地内存而不是固定大小的内存区域。</li><li><strong>栈（Stack）</strong>： 每个线程创建时都会有一个私有的栈，用于存储局部变量表、操作数栈、动态链接、返回地址等信息。每个方法调用都会在线程栈中创建一个栈帧（Frame），当方法调用结束时，对应的栈帧也会被弹出。</li><li><strong>程序计数器（Program Counter Register）</strong>： 程序计数器是一块较小的内存空间，它的作用可以看作是当前线程所执行的字节码指令的索引指示器。对于Java来说，每个线程都有自己的程序计数器，它是线程私有的。</li><li><strong>本地方法栈（Native Method Stack）</strong>： 与Java方法使用的Java栈相对应，本地方法栈为本地方法服务。具体实现可能依赖于具体的JVM实现；有些JVM可能会将它和Java栈合并。</li><li><strong>直接内存（Direct Memory）</strong>： 直接内存并不是JVM运行时数据区的一部分，但它仍然经常被使用。它指的是通过java.nio.ByteBuffer.allocateDirect分配的内存，这部分内存是在JVM之外的，因此不受JVM的垃圾回收机制控制。然而，由于它可以绕过JVM的堆内存限制，并且能够提高I/O操作的性能，所以在某些场景下非常有用。</li></ol><h2 id="方法区" tabindex="-1">方法区 <a class="header-anchor" href="#方法区" aria-label="Permalink to &quot;方法区&quot;">​</a></h2><h3 id="什么是方法区" tabindex="-1">什么是方法区？ <a class="header-anchor" href="#什么是方法区" aria-label="Permalink to &quot;什么是方法区？&quot;">​</a></h3><p><img src="'+l+'" alt="images/KGcTbGwKooR7rkxpRPwcmAO2nmg.png"></p><p>images/KGcTbGwKooR7rkxpRPwcmAO2nmg.png</p><p>在HotSpot JVM中，方法区是一个逻辑上的概念，也被称为非堆（Non-Heap），一般用来存储类加载信息、static变量、JIT实时编译缓存的代码、常量池（Constants Pool）等。不同版本的Java其方法区的实现方式不同，在JDK 8之前，采用的是“永久代”来实现方法区，而在JDK 8之后则是采用MetaSpace的方式来实现。总的来说，方法区的基本特点如下：</p><ul><li><strong>共享性：</strong> 方法区与Java堆一样，是各个线程共享的内存区域。</li><li><strong>创建和内存空间：</strong> 方法区在JVM启动时被创建，实际的物理内存空间和Java堆一样，可以是不连续的。</li><li><strong>大小和可扩展性：</strong> 方法区的大小，就像堆空间一样，可以选择固定大小或可扩展。</li><li><strong>溢出问题：</strong> 方法区的大小决定了系统能够保存多少个类。如果系统定义了太多的类，导致方法区溢出，虚拟机将抛出内存溢出错误，例如 java.lang.OutOfMemoryError: PermGen space 或 java.lang.OutOfMemoryError: Metaspace。</li><li><strong>释放：</strong> 关闭JVM将释放方法区的内存空间。 方法区是用于存储类信息、常量池、静态变量等数据的区域，对于Java虚拟机的正常运行和类加载等都具有重要作用。</li></ul><h4 id="方法区的前世今生" tabindex="-1">方法区的前世今生 <a class="header-anchor" href="#方法区的前世今生" aria-label="Permalink to &quot;方法区的前世今生&quot;">​</a></h4><p><img src="'+n+'" alt="images/XzUObfWTyoMamzxjxAGcLm6qnec.png"></p><p>images/XzUObfWTyoMamzxjxAGcLm6qnec.png</p><p>在JDK 6中，方法区的实现和JVM的定义几乎完全一样，其实现方式是永久代，是完全独立于Heap的一块儿内存区域，其中类信息、静态变量、运行时常量池、static变量以及字符串常量等内容都是存储在方法区的。但是，由于StringTable存在于方法区，当Java程序中大量生成较大的字符串对象的时候，就可能造成方法区OOM。</p><p><img src="'+s+'" alt="images/B2ULbG6oTo7zsZxuYcccOl92nPf.png"></p><p>images/B2ULbG6oTo7zsZxuYcccOl92nPf.png</p><p>在JDK 7中，为了避免方法区频繁溢出，将StringTable和静态变量这两个容易造成方法区溢出的部分移动到了堆内存当中去。jdk7 中将 StringTable 放到了堆空间中。因为永久代的回收率很低，在 full gc 的时候才会触发。 而 full gc 是老年代的空间不足，永久代不足时才会触发。这就导致 StringTable 回收率不高。而我们开发中会有大量的字符串被创建，回收率低，导致永久代内存不足。放到堆里，能及时回收内存。</p><p><img src="'+p+'" alt="images/OEZVb97dUoeolyxqLAucvhj3n6g.png"></p><p>images/OEZVb97dUoeolyxqLAucvhj3n6g.png</p><p>在JDK 8之后就没有永久代的概念了，而且方法区也完全成为了逻辑概念。方法区在JDK 8之后的对应实现应该是MetaSpace，MetaSpace是由Native内存实现的由操作系统直接管理。类型信息、字段、方法、常量保存在本地内存MetaSpace当中，但字符串常量池、静态变量仍在堆中。这样以来MetaSpace 的空间上限和操作系统相关，当大量加载类的时候不用担心方法区溢出。</p><h5 id="永久代-permanent-generation-和元空间-metaspace-区别" tabindex="-1">永久代（Permanent Generation）和元空间（Metaspace）区别？ <a class="header-anchor" href="#永久代-permanent-generation-和元空间-metaspace-区别" aria-label="Permalink to &quot;永久代（Permanent Generation）和元空间（Metaspace）区别？&quot;">​</a></h5><p>永久代是Java虚拟机堆内存的一部分，主要用于存储类的元数据信息。包括类的结构、方法、字段、注解等。在Java 8及之前的版本，永久代有一定的固定大小，当存储的类信息较多时容易导致永久代溢出。此时可能会出现OutOfMemoryError: PermGen space错误。</p><p>在Java 8及之后的版本，永久代被元空间所取代。元空间不再与Java堆关联，而是使用**本地内存（native memory）**来存储类的元数据信息。这样，就不再存在永久代的大小限制问题。元空间的大小受限于本地内存的大小，可以动态地扩展，减轻了类元数据区溢出的问题。更多的区别和特点如下：</p><p>总体而言，元空间的引入解决了永久代存在的一些限制和问题，提高了对类元数据信息的管理效率和灵活性。在Java 8及之后的版本，开发者不再需要过于关注永久代的大小调优，而是需要关注本地内存的使用情况。</p><h4 id="设置方法区大小" tabindex="-1"><strong>设置方法区大小</strong> <a class="header-anchor" href="#设置方法区大小" aria-label="Permalink to &quot;**设置方法区大小**&quot;">​</a></h4><h5 id="jdk-7-及之前的实现" tabindex="-1">JDK 7 及之前的实现 <a class="header-anchor" href="#jdk-7-及之前的实现" aria-label="Permalink to &quot;JDK 7 及之前的实现&quot;">​</a></h5><p>在JDK 7及之前，方法区的大小可以通过 -XX:PermSize 参数进行设置，用于指定永久代的初始分配空间。通过 -XX:MaxPermSize 参数设定永久代的最大可分配空间。当JVM加载的类信息容量超过了这个值，就会抛出 OutOfMemoryError: PermGen space 异常，如下表：</p><h5 id="jdk-8-及以后的实现" tabindex="-1">JDK 8 及以后的实现 <a class="header-anchor" href="#jdk-8-及以后的实现" aria-label="Permalink to &quot;JDK 8 及以后的实现&quot;">​</a></h5><p>在JDK 8及以后，方法区的永久代被元空间（Metaspace）所取代，可以通过 -XX:MetaspaceSize 和 -XX:MaxMetaspaceSize 参数来设置元空间的大小。默认值依赖于平台， -XX:MaxMetaspaceSize 的值为-1，则表示没有限制。与永久代不同，如果不指定大小，默认情况下，虚拟机会耗尽所有可用的系统内存。当元数据大小超过可用内存时，虚拟机会抛出 OutOfMemoryError: Metaspace 异常。</p><ul><li>-XX:MetaspaceSize: 用于设置初始的元空间大小。对于64位的服务器JVM，默认值为21MB。这是初始的高水位线，一旦达到这个水位线，Full GC将被触发，卸载不再存活的类，然后重置高水位线。新的高水位线取决于GC释放了多少空间。如果释放的空间不足，适当提高该值，不超过MaxMetaspaceSize。如果释放的空间过多，则适当降低该值。</li><li>如果初始化的高水位线设置过低，会导致高水位线调整多次，观察垃圾回收器的日志可以看到Full GC的多次调用。为了避免频繁的GC，建议将 -XX:MetaspaceSize 设置为一个相对较高的值。</li></ul><h4 id="方法区的内部结构" tabindex="-1">方法区的内部结构 <a class="header-anchor" href="#方法区的内部结构" aria-label="Permalink to &quot;方法区的内部结构&quot;">​</a></h4><p>方法区在 Java 虚拟机内存中扮演了类的元数据存储和管理的角色。它不仅保存了类的结构信息，还包括了支持类运行时行为的相关数据。方法区的设计使得虚拟机能够高效地加载、存储和管理类信息，保证类的正确性和一致性。</p><p><img src="'+c+'" alt="images/Gr2Ubn4lgonp33xhkYjcY60gnoe.png"></p><p>images/Gr2Ubn4lgonp33xhkYjcY60gnoe.png</p><p>方法区主要用于存储已被虚拟机加载的类信息、常量、静态变量以及即时编译器编译后的代码缓存等，如下：</p><h5 id="类型信息" tabindex="-1">类型信息 <a class="header-anchor" href="#类型信息" aria-label="Permalink to &quot;类型信息&quot;">​</a></h5><p>对于每个加载的类型（类class、接口interface、枚举enum、注解annotation），JVM 方法区中存储以下类型信息：</p><ol><li><strong>类型的完整有效名称：</strong> 例如，对于类java.lang.String，存储的是完整的包名和类名。</li><li><strong>类型直接父类的完整有效名：</strong> 对于接口或是java.lang.Object，它们没有直接的父类。</li><li><strong>类型的修饰符：</strong> 存储类型的修饰符，可能包括public、abstract、final等的某个子集，用于描述该类型的访问权限、抽象性质和是否可以被继承等信息。</li><li><strong>类型直接接口的一个有序列表：</strong> 存储类型实现的接口列表，有序表示接口的顺序，这对于多接口实现的情况很重要。 这些信息使得虚拟机能够准确地了解每个加载类型的结构和关系，包括其继承层次、实现接口、访问权限等。这对于类的加载、链接和运行时行为都具有重要作用。</li></ol><h5 id="运行时常量池-vs-常量池-constant-pool" tabindex="-1"><strong>运行时常量池 vs 常量池（Constant Pool）</strong> <a class="header-anchor" href="#运行时常量池-vs-常量池-constant-pool" aria-label="Permalink to &quot;**运行时常量池 vs 常量池（Constant Pool）**&quot;">​</a></h5><p>常量池包含了编译期生成的各种字面量和符号引用，包括字符串、数字、类和方法的符号引用等。在运行时，这些常量供虚拟机使用。</p><ul><li><strong>方法区中包含了运行时常量池：</strong> 运行时常量池是方法区的一部分，用于存储编译期生成的各种字面量和符号引用。在类加载后，字节码文件中的常量池会被加载到运行时常量池中，供运行时使用。运行时常量池是在程序运行期间动态生成和修改的，可以包含字符串、数字、类和方法的符号引用等信息。它在方法区中的位置使得虚拟机能够更加灵活地管理和使用常量池中的信息。</li><li><strong>字节码文件中包含了常量池：</strong> 字节码文件的常量池是在编译期生成的，包含了类中的常量、类名、字段名、方法名等信息。它是一种静态的、不可变的常量池，保存了在编译时确定的字面量和符号引用。字节码文件中的常量池在类加载时被加载到方法区的运行时常量池中，供虚拟机执行时使用。 总体而言，字节码文件中的常量池是类的静态结构的一部分，而运行时常量池是类在运行时动态生成的。运行时常量池的动态性使得它可以包含更多在运行期间生成的信息，而字节码文件中的常量池则提供了类的静态元数据。这两者的结合使得虚拟机能够更好地支持动态语言特性和类的动态变化。</li></ul><h5 id="static变量" tabindex="-1">static变量 <a class="header-anchor" href="#static变量" aria-label="Permalink to &quot;static变量&quot;">​</a></h5><h6 id="non-final-的static变量" tabindex="-1">non-final 的static变量 <a class="header-anchor" href="#non-final-的static变量" aria-label="Permalink to &quot;non-final 的static变量&quot;">​</a></h6><p>静态变量（static）和类紧密关联在一起，随着类的加载而加载，它们成为类数据在逻辑上的一部分。non-final 的static变量被类的所有实例共享，即使没有类实例时，也可以通过类名直接访问。</p><p>non-final的static变量的特点在于其值可以在程序运行过程中被修改，因此它们可以被看作是在类级别共享的可变状态。这使得它们适用于存储在整个类生命周期中需要共享的数据，例如计数器、配置信息等。类加载时分配内存空间用于存储这些静态变量，并且它们在整个应用程序的生命周期内保持不变，直到程序结束或类被卸载。</p><p>non-final的static变量的修改会影响到所有实例，因为它们在逻辑上属于整个类，而不是某个特定的实例。这也意味着不同实例之间共享相同的non-final的static变量值。</p><h6 id="全局常量-static-final" tabindex="-1"><strong>全局常量：static final</strong> <a class="header-anchor" href="#全局常量-static-final" aria-label="Permalink to &quot;**全局常量：static final**&quot;">​</a></h6><p>被声明为 final 的类变量在编译时会被分配，每个全局常量在编译的时候就会被确定了。这意味着在程序运行时，这些全局常量的值是不可修改的，它们被视为一种稳定的、不可变的数据。</p><p>使用 static final 声明的变量通常用于表示在整个类范围内都保持不变的常量值。这些常量可以在类加载时被初始化，且一经初始化就无法被修改。由于它们是静态的，可以通过类名直接访问，而不需要创建类的实例。</p><p>全局常量的命名通常采用大写字母和下划线的命名规范，以便清晰地区分它们与普通变量。例如：</p><p>public class Constants { public static final int MAX_VALUE = 100; public static final String DEFAULT_NAME = &quot;John Doe&quot;; }</p><p>在上述例子中，MAX_VALUE 和 DEFAULT_NAME 都是全局常量，它们的值在编译时确定，并且在运行时不可修改。</p><h5 id="即时编译器-jit-编译后的代码缓存" tabindex="-1"><strong>即时编译器（JIT）编译后的代码缓存：</strong> <a class="header-anchor" href="#即时编译器-jit-编译后的代码缓存" aria-label="Permalink to &quot;**即时编译器（JIT）编译后的代码缓存：**&quot;">​</a></h5><p>方法区在 Java 虚拟机中不仅存储类的元数据信息，还承担了即时编译器（JIT）生成的本地机器代码的存储任务。即时编译器是一种优化技术，它将部分热点代码（经常执行的代码路径）编译成本地机器代码，以提高程序的执行性能。具体而言，方法区中存储了以下内容：</p><ol><li><strong>本地机器代码：</strong> JIT 编译器将部分 Java 字节码编译成本地机器代码，这样可以更高效地执行。这些本地机器代码通常涉及程序的热点部分，即频繁执行的代码段。</li><li><strong>代码缓存：</strong> 编译后的本地机器代码被缓存，以避免重复编译相同的代码。缓存机制有助于减少重复工作，提高程序的运行效率。当相同的代码段再次执行时，虚拟机可以直接使用缓存中的本地机器代码，而不必重新进行编译。 通过将热点代码编译成本地机器代码，并进行缓存，JIT 编译器在运行时动态地优化程序的性能。这种动态编译和优化的机制使得虚拟机能够更好地适应不同的程序运行情境，提高程序的执行效率。方法区的设计使得它能够承担这一重要角色，为 Java 程序的性能提供支持。</li></ol><h5 id="域-field-信息" tabindex="-1">域（Field)信息 <a class="header-anchor" href="#域-field-信息" aria-label="Permalink to &quot;域（Field)信息&quot;">​</a></h5><p>JVM 在方法区中保存类型的所有域的相关信息以及域的声明顺序。域的相关信息包括：</p><ol><li><strong>域名称：</strong> 表示字段的名字，例如，对于类中的属性，如 int age; 中的 “age”。</li><li><strong>域类型：</strong> 表示字段的数据类型，例如，对于类中的属性，如 int age; 中的 “int”。</li><li><strong>域修饰符：</strong> 表示字段的修饰符，可能包括以下某个子集：</li></ol><ul><li>public: 表示该字段对所有类可见。</li><li>private: 表示该字段仅对声明它的类可见。</li><li>protected: 表示该字段对其自雷和同一包内的类可见。</li><li>static: 表示该字段为静态字段，属于类而非实例。</li><li>final: 表示该字段为常量，不能被修改。</li><li>volatile: 表示该字段可能会被多个线程同时访问，因此需要进行同步处理。</li><li>transient: 表示该字段不会被序列化。 这些信息使得虚拟机能够了解每个字段的名称、类型、访问权限、是否为静态字段以及其他修饰信息，从而能够正确地处理字段的访问和操作。这对于类的实例化、访问字段以及字段的初始化等操作都具有重要作用。</li></ul><h5 id="方法-method-信息" tabindex="-1">方法（Method) 信息 <a class="header-anchor" href="#方法-method-信息" aria-label="Permalink to &quot;方法（Method) 信息&quot;">​</a></h5><p>JVM 必须保存所有方法的以下信息，与域信息类似，包括声明顺序：</p><ol><li><strong>方法名称：</strong> 表示方法的名字，例如，对于一个方法，如 public void doSomething() 中的 “doSomething”。</li><li><strong>方法的返回类型：</strong> 表示方法返回值的数据类型，例如，对于一个方法，如 public int calculate() 中的 “int”。</li><li><strong>方法参数的数量和类型（按顺序）：</strong> 表示方法接收的参数的数量和类型，例如，对于一个方法，如 public void setName(String name, int age) 中的 “(String, int)”。</li><li><strong>方法的修饰符：</strong> 表示方法的修饰符，可能包括以下某个子集：</li></ol><ul><li>public: 表示该方法对所有类可见。</li><li>private: 表示该方法仅对声明它的类可见。</li><li>protected: 表示该方法对其自雷和同一包内的类可见。</li><li>static: 表示该方法为静态方法，属于类而非实例。</li><li>final: 表示该方法不能被子类覆写。</li><li>synchronized: 表示该方法在多线程环境中需要同步。</li><li>native: 表示该方法用其他语言（如C）实现。</li><li>abstract: 表示该方法没有实现，需要在子类中被覆写。</li></ul><ol><li><strong>方法的字节码（bytecodes)、操作数栈、局部变量表及大小：</strong> 这些信息用于存储方法的具体实现，包括方法体的字节码指令、操作数栈的状态、局部变量表的内容及其大小。这些信息对于虚拟机执行方法体的字节码指令非常关键。</li><li><strong>异常表：</strong> 用于存储方法中可能抛出的异常的处理信息，包括每个异常处理块的开始位置、结束位置、代码处理在程序计数器中的偏移地址以及被捕获的异常类的常量池索引。这些信息帮助虚拟机在出现异常时进行适当的处理。 这些方法信息使得虚拟机能够正确地加载、解析和执行方法，处理方法的调用、返回值、异常处理等操作。</li></ol><h4 id="字符串常量、静态变量数据存放区域变化" tabindex="-1"><strong>字符串常量、静态变量数据存放区域变化</strong> <a class="header-anchor" href="#字符串常量、静态变量数据存放区域变化" aria-label="Permalink to &quot;**字符串常量、静态变量数据存放区域变化**&quot;">​</a></h4><p>在 Java 6 中，所有常量池数据都被存放在永久代中。永久代是 Java 虚拟机内存区域的一部分，用于存储类的元数据、常量池等信息。这个阶段，永久代就是方法区的实现方案。</p><p>然而，随着 Java 7 的引入，HotSpot 虚拟机对永久代的管理进行了调整。具体而言，HotSpot 将字符串常量和静态变量数据从永久代迁移到了堆中。这个变化的目的是为了缓解永久代的内存压力，因为永久代在一些场景下容易发生内存溢出。</p><p>在 Java 8 中，这个变化并没有被保留了下来，字符串常量和静态变量数据仍然存放在堆中，而不再是永久代。这意味着在 Java 8 中，虽然常量池在 JVM 规范中定义为方法区的一部分，但实际上部分常量池的内容是保存在堆中的。</p><p>总体来说，Java 虚拟机规范将常量池归类为方法区的一部分，但HotSpot 在实际实现中对部分常量池内容进行了迁移，将其保存在堆中。这一调整旨在提高对于字符串常量和静态变量数据的内存管理效率。</p><h4 id="方法区oom-java-8之后" tabindex="-1">方法区OOM（Java 8之后） <a class="header-anchor" href="#方法区oom-java-8之后" aria-label="Permalink to &quot;方法区OOM（Java 8之后）&quot;">​</a></h4><p>在Java 8及之后的版本，永久代（PermGen）被元空间（Metaspace）所取代。因此，发生在Java 8及之后版本的方法区OOM通常指的是Metaspace的OOM。</p><p>Metaspace是一块与堆不同的本地内存区域，它用于存储类的元数据信息，包括类的结构、方法、字段等信息。Metaspace的OOM与永久代的OOM有一些相似之处，但也有一些区别。</p><p>常见原因导致Metaspace的OOM：</p><ol><li><strong>动态生成类过多：</strong> 如果应用程序在运行时动态生成大量的类，例如使用字节码操作库或动态代理，可能导致Metaspace内存不足。</li><li><strong>持续加载大量不同的类：</strong> 如果应用程序持续加载大量不同的类，Metaspace可能会被耗尽。</li><li><strong>缺少Metaspace的垃圾回收：</strong> 在Java 8及之后的版本，Metaspace不再有垃圾回收的概念，因此如果动态生成的类或加载的类不再使用，Metaspace也不会自动释放相关内存。这可能导致Metaspace逐渐增长，最终耗尽内存。 解决Metaspace的OOM：</li><li><strong>调整Metaspace大小：</strong> 可以通过JVM参数（如-XX:MaxMetaspaceSize）来调整Metaspace的大小。增大Metaspace的内存限制可能会缓解OOM，但需要确保整个系统内存足够。</li><li><strong>优化类加载和卸载：</strong> 确保应用程序中只加载必要的类，避免不必要的类加载。使用工具监控类加载和卸载的情况，查看是否有无用的类没有被卸载。</li><li><strong>检查动态生成类的逻辑：</strong> 如果应用程序中有动态生成类的逻辑，确保生成的类数量有限，并且可以被及时卸载。</li><li><strong>监控Metaspace使用情况：</strong> 使用JVM的监控工具，如VisualVM或JConsole，来监控Metaspace的使用情况，及时发现潜在的OOM问题。 总的来说，Metaspace的OOM问题需要特别关注动态生成类的逻辑和类加载的行为，以及及时调整Metaspace的内存大小。</li></ol><h5 id="方法区的垃圾回收" tabindex="-1">方法区的垃圾回收 <a class="header-anchor" href="#方法区的垃圾回收" aria-label="Permalink to &quot;方法区的垃圾回收&quot;">​</a></h5><p>Java 8及之后的版本使用元空间（Metaspace）替代了永久代，Metaspace是在堆之外的本地内存。其空间的大小默认不受限制，可以根据系统的实际内存情况动态扩展。因此，不再存在永久代溢出的问题，但仍然需要关注系统内存的使用情况。</p><p>MetaSpace的垃圾回收主要发生在类的卸载时，一般由JVM自动完成。当一个类不再被引用，而且它的加载器也不再存活，MetaSpace会触发对该类的垃圾回收。MetaSpace的垃圾回收主要涉及到不再使用的类的卸载。判定一个类型是否属于“不再被使用的类”的条件则比较苛刻，需要同时满足以下三个条件：</p><ol><li>该类的所有实例都已经被回收，即Java堆中不存在该类及其任何派生子类的实例。</li><li>加载该类的类加载器已经被回收，这个条件通常难以达成，除非是一些特殊场景如OSGI、JSP的重加载等。</li><li>该类对应的java.lang.Class对象没有在任何地方被引用，无法通过反射访问该类的方法。 Java虚拟机被允许对满足上述三个条件的无用类进行回收，这里强调的是“被允许”，而不是像对象一样没有引用就必然回收。</li></ol><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>方法区是Java运行时内存区域非常重要的一个区域，这个区域主要用来存储一些类加载信息、static变量、运行时常量池和JIT实时编译的缓存代码等。</p><p>实际上，方法区到现在已经是一个逻辑概念了，在JDK6之前方法区的实现方式是永久带，永久带是一块独立的内存区域，几乎和逻辑上的方法区保持一致。到JDK8之后，方法区的实现方法改成了MetaSpace，MetaSpace是一块儿属于Native内存的区域，只负责存储类相关的信息、static变量和JIT实时编译的缓存代码等。像字符串常量和常量池的存储区域就被放到了Heap中，此时方法区已经完全成为了一个逻辑上的概念。</p><p>最后，对于MetaSpace来说一般很难出现OOM的情况，因为MetaSpace出现OOM意味着整个Native的内存已经被耗尽，但是仍然可以通过调整MetaSpace的相关参数来优化JVM的性能。</p><h2 id="虚拟机栈" tabindex="-1">虚拟机栈 <a class="header-anchor" href="#虚拟机栈" aria-label="Permalink to &quot;虚拟机栈&quot;">​</a></h2><h3 id="栈与栈帧" tabindex="-1">栈与栈帧 <a class="header-anchor" href="#栈与栈帧" aria-label="Permalink to &quot;栈与栈帧&quot;">​</a></h3><p>我们知道当程序运行的时候，需要一个”栈“的数据结构来完成对源代码转译而来的操作指令（JVM的操作指令）的压栈和出栈等操作，来实际运行程序。在Java中程序的运行一般是以线程为单位的，而虚拟机栈就是Java线程专属的栈空间。每个线程创建之后都会单独申请自己独立的一个栈空间，每个方法的调用都会对应着一个<strong>栈帧</strong>，栈帧包含局部变量表、操作数栈、动态连接、方法出口等。</p><p><img src="'+d+'" alt="images/K5o3bAwpdoFi8kxjJvic4XN4nsg.png"></p><p>images/K5o3bAwpdoFi8kxjJvic4XN4nsg.png</p><p>在 Java 虚拟机中，每个线程存在着一个虚拟机栈，每个方法的执行都对应着一个栈帧，栈帧的入栈和出栈过程，以及栈帧之间的切换和返回值传递。栈和栈帧是实现方法调用和执行的重要机制：</p><ol><li><strong>栈与栈帧：</strong></li></ol><ul><li><strong>栈：</strong> Java 虚拟机栈是线程私有的，用于存储线程执行方法时的<strong>局部变量</strong>、<strong>操作数栈、动态链接、方法出口</strong>等信息，每个线程都有自己的 Java 虚拟机栈。</li><li><strong>栈帧：</strong> 每个方法的执行对应一个栈帧。栈帧包含了<strong>局部变量表、操作数栈、动态链接、方法出口等信息</strong>。每次方法调用时都会创建一个新的栈帧，该栈帧被推入虚拟机栈，成为当前活动栈帧。</li></ul><ol><li><strong>栈帧的入栈和出栈：</strong></li></ol><ul><li><strong>入栈：</strong> 当一个方法被调用时，会在虚拟机栈顶创建一个新的栈帧，该栈帧成为当前活动栈帧，PC 寄存器指向当前活动栈帧的地址，执行方法的指令序列从该地址开始。</li><li><strong>出栈：</strong> 当方法执行完成时，对应的栈帧会被移除，控制权回到前一个栈帧。前一个栈帧中的返回值成为当前活动栈帧的一个操作数，继续执行。</li></ul><ol><li><strong>栈帧的切换：</strong></li></ol><ul><li>当一个方法调用其他方法时，会创建一个新的栈帧，该栈帧成为当前活动栈帧，只有当前活动栈帧中的局部变量才能被使用，其他栈帧中的局部变量不可访问。</li><li>当新的栈帧中的方法执行完毕后，该栈帧被移除，之前的栈帧重新成为活动栈帧，继续执行。</li></ul><h4 id="栈帧" tabindex="-1">栈帧 <a class="header-anchor" href="#栈帧" aria-label="Permalink to &quot;栈帧&quot;">​</a></h4><p><img src="'+h+'" alt="images/UMjKbgRHlos11zxQyPWcsWwanCF.png"></p><p>images/UMjKbgRHlos11zxQyPWcsWwanCF.png</p><p>Java 虚拟机中的栈帧（Stack Frame）是虚拟机运行时数据区中虚拟机栈的栈元素，用于支持虚拟机进行方法调用和方法执行，每个方法在执行时都对应着一个栈帧。一个方法从调用开始到执行完成，对应着一个栈帧在虚拟机栈中从入栈到出栈的过程。而当前栈帧则是执行引擎关注的有效栈帧，决定了当前执行的方法。</p><p><strong>栈帧的组成</strong>包括了<strong>局部变量表、操作数栈、动态连接、方法返回地址等信息</strong>。在编译代码时，局部变量表和操作数栈的大小已经确定，并写入方法表的 Code 属性中。因此，栈帧所需的内存不受程序运行期变量数据的影响，仅取决于虚拟机的实现。</p><p>就<strong>栈帧的状态</strong>来说，一个线程中可能存在很多方法调用，方法之间相互调用，形成一个方法调用链。对于JVM来说，只有当前栈帧才是有效的，被称为当前栈帧（Current Stack Frame）。当前栈帧关联的方法称为当前方法（Current Method）。JVM只针对当前栈帧进行操作，执行引擎运行的所有字节码指令都是针对当前栈帧进行的。</p><h5 id="局部变量表" tabindex="-1">局部变量表 <a class="header-anchor" href="#局部变量表" aria-label="Permalink to &quot;局部变量表&quot;">​</a></h5><p>局部变量表（Local Variable Table）是Java虚拟机中的一块内存区域，用于存储方法执行过程中的局部变量。每个方法在执行时都会创建一个栈帧（Stack Frame），栈帧中包括局部变量表、操作数栈、动态链接、方法返回地址等信息。局部变量表就是栈帧中的一部分，用于存储方法中定义的局部变量。以下是局部变量表的一些关键特点：</p><ol><li><strong>存储局部变量：</strong> 局部变量表用于存储方法中的局部变量，包括方法参数和在方法体内部定义的局部变量。系统不会为局部变量赋予初始值，与实例变量和类变量不同，局部变量在准备阶段不会被赋予初始值。</li><li><strong>数据类型：</strong> 局部变量表中的每个槽位可以存储一个数据，而数据的类型可以是各种基本数据类型（如int、float、double、long等）以及对象引用。局部变量表的存储以变量槽（Slot）为最小单位。在32位虚拟机中，一个Slot可以存放32位（4字节）以内的数据类型，包括boolean、byte、char、short、int、float、reference和returnAddress等八种类型。对于64位长度的数据类型（如long和double），虚拟机以高位对齐方式为其分配两个连续的Slot空间，相当于将一次long和double数据类型读写分割成两次32位读写。并且，Slot是可以重用的，当Slot中的变量超出作用域时，下一次分配Slot时会覆盖原有的数据。对于对象的引用存储在Slot中，会影响垃圾回收，即如果被引用，对象将不会被回收</li><li><strong>编译时确定：</strong> 局部变量表的容量在编译时就已经确定了，因为它与方法的代码结构直接相关。每个局部变量表的槽位可以存储一个数据，而槽位的索引从0开始。</li><li><strong>作用域：</strong> 局部变量表的作用域仅限于方法体内，当方法执行结束时，局部变量表的内容会被销毁。</li><li><strong>访问方式：</strong> 局部变量表中的局部变量可以通过索引访问。例如，iload_1 指令表示将索引为1的局部变量加载到操作数栈中。 以下是add方法和相应的字节码，说明了局部变量表的使用：</li></ol><p>public int add(int a, int b) { int result = a + b; return result; }</p><p>使用javac命令编译之后相应的字节码包含以下的指令（具体编译字节码的方法可以<a href="https://mp.weixin.qq.com/s?__biz=MzkzMjI0MDY3Mw==&amp;mid=2247484211&amp;idx=1&amp;sn=ab014d1d3df5cb478a12d54cce6fd488&amp;chksm=c25f8f7df528066b0d75f670f6668d3cef5d0eb0a2d24935ac48fd5061694a715d4ead18d701#rd" target="_blank" rel="noreferrer">参考这里</a>）：</p><p>stack=2, locals=4, args_size=3 0: iload_1 1: iload_2 2: iadd 3: istore_3 4: iload_3 5: ireturn</p><p>当add方法执行之前，JVM会将add方法构造成一个栈帧推入main线程虚拟机栈中，而参数a和b会作为局部变量，被放置到局部变量表当中。而iload_1和iload_2会分别从局部变量表中读取第一个和第二个元素进行计算。</p><p>而add方法是Demo类的成员函数，所以add方法的局部变量表中会默认带一个this指针并放在0号索引位置。参数a和b会按照位置依次被放到局部变量表中。</p><h5 id="操作数栈" tabindex="-1">操作数栈 <a class="header-anchor" href="#操作数栈" aria-label="Permalink to &quot;操作数栈&quot;">​</a></h5><p>在Java虚拟机中，操作数栈（Operand Stack）是一个用于存储操作数的临时存储区域。它是虚拟机栈的一部分，用于执行方法时保存中间结果、参数和返回值。</p><p>在方法执行的过程中，操作数栈被用于执行各种字节码指令。每个线程都有自己的虚拟机栈，而每个方法在执行时都会有一个对应的栈帧（Stack Frame），栈帧中包含了局部变量表、操作数栈以及一些额外的信息。以下是操作数栈的一些关键特性：</p><ol><li><strong>栈的结构：</strong> 操作数栈是一个后进先出（LIFO）的栈结构，类似于数据结构中的栈。最后压入栈的元素最先被弹出。</li><li><strong>存储操作数：</strong> 操作数栈主要用于存储方法执行时需要操作的数据，包括方法参数、中间计算结果以及方法返回值。</li><li><strong>字节码执行：</strong> 在执行方法时，字节码中的各种指令会涉及到对操作数栈的读取和写入操作。例如，将局部变量加载到操作数栈、进行算术运算、方法调用等都涉及到对操作数栈的操作。</li><li><strong>临时存储：</strong> 操作数栈的内容是临时性的，它在方法执行期间用于暂存数据。一旦方法执行结束，操作数栈的内容也随之被销毁。 如下面的Java代码，这里简单实现了一个add的方法：</li></ol><p>public int add(int a, int b) { int result = a + b; return result; }</p><p>使用javac命令编译之后相应的字节码包含以下的指令（具体编译字节码的方法可以<a href="https://mp.weixin.qq.com/s?__biz=MzkzMjI0MDY3Mw==&amp;mid=2247484211&amp;idx=1&amp;sn=ab014d1d3df5cb478a12d54cce6fd488&amp;chksm=c25f8f7df528066b0d75f670f6668d3cef5d0eb0a2d24935ac48fd5061694a715d4ead18d701#rd" target="_blank" rel="noreferrer">参考这里</a>）：</p><p>iload_1 // 将局部变量 a 推入操作数栈 iload_2 // 将局部变量 b 推入操作数栈 iadd // 从操作数栈中弹出两个值，相加，将结果推入操作数栈 istore_3 // 将操作数栈的结果存储到局部变量 result ireturn // 将结果从方法中返回</p><p>在这个例子中，操作数栈用于存储局部变量 a 和 b 的值，并在 iadd 指令中执行加法操作，将结果存储到局部变量 result 中。ireturn 指令将最终结果从方法中返回。整个过程中，操作数栈充当了中间计算结果的存储区域，具体如下列图：</p><p><img src="'+g+'" alt="images/CpPXbTpWxonI2kxLCDTcT3oBnYe.png"></p><p>images/CpPXbTpWxonI2kxLCDTcT3oBnYe.png</p><ul><li>iload_1 和 iload_2 会分别将局部变量表中索引为1和索引为2的变量压入操作数栈，为后面进行运算做准备。</li></ul><p><img src="'+u+'" alt="images/RhsPbdgDuoOcDRxYB3Vcd2MHnYd.png"></p><p>images/RhsPbdgDuoOcDRxYB3Vcd2MHnYd.png</p><ul><li>iadd操作会将操作数栈顶的两个元素出栈，并给到CPU（这里并不严谨，逻辑上可以这样理解）进行加法运算，运算的结果再压回操作数栈；</li><li>istore操作会将操作数栈顶的元素出栈，并将该元素放回局部变量表；</li><li>ireturn操作会返回一个int值，就是我们刚刚计算出的c=3；</li></ul><h5 id="动态连接" tabindex="-1">动态连接 <a class="header-anchor" href="#动态连接" aria-label="Permalink to &quot;动态连接&quot;">​</a></h5><p>在Java源文件被编译成为字节码文件的时候，所有的变量和方法都会被转换成符号引用保存在class文件的常量池当中。描述一个方法调用另外一个方法的时候，就是通过常量池中指向方法的符号引用来进行表示的。</p><p>在Java虚拟机栈帧中，每个方法的栈帧都包含了一部分用于存储动态连接信息的数据结构，具体来说存储的是“指向运行时常量池中该栈帧所属方法的引用”——动态连接。</p><p>“动态连接”可以使得Java在运行过程中能够快速的获取方法相关的信息，这些信息包括方法所属的类、方法的字节码索引、字段和方法的符号引用等。在运行时，当调用方法或访问字段时，这些符号引用会在动态连接的过程中被解析为实际的内存地址，从而快速的完成方法调用或字段访问的操作。</p><p>动态连接在Java虚拟机中是为了支持多态性、延迟解析和提高程序的灵活性而设计的，这使得在程序运行时期进行动态绑定和解析，而不是在编译时期确定所有的引用关系。</p><h5 id="方法返回地址" tabindex="-1">方法返回地址 <a class="header-anchor" href="#方法返回地址" aria-label="Permalink to &quot;方法返回地址&quot;">​</a></h5><p>方法返回地址是指在方法执行过程中，记录了方法调用点的地址，以便在方法执行完成后能够回到调用它的地方。在 Java 虚拟机的栈帧中，方法返回地址通常是存储在栈帧数据结构的一部分，用于指示方法返回的位置。</p><p>当一个方法被调用时，调用点的地址会被记录下来，然后方法开始执行。在方法执行的过程中，如果遇到返回语句，虚拟机会利用保存的方法返回地址回到调用点，继续执行调用者方法的下一条指令。</p><p>在栈帧中，方法返回地址的保存方式依赖于具体的虚拟机实现和硬件架构。通常，它会被保存在栈帧的特定位置，以确保在方法返回时能够被正确地取出和使用。</p><p>需要注意的是，方法返回地址通常是指明下一条指令的地址，而不是直接指向调用语句的地址。这是因为在方法执行期间可能会有一些中间操作，如异常处理、同步块的释放等，因此返回地址不仅仅是简单的调用点地址。</p><h4 id="jvm栈与stack-over-flow分析" tabindex="-1">JVM栈与Stack Over Flow分析 <a class="header-anchor" href="#jvm栈与stack-over-flow分析" aria-label="Permalink to &quot;JVM栈与Stack Over Flow分析&quot;">​</a></h4><h5 id="运行java代码时设置栈大小方法" tabindex="-1">运行Java代码时设置栈大小方法 <a class="header-anchor" href="#运行java代码时设置栈大小方法" aria-label="Permalink to &quot;运行Java代码时设置栈大小方法&quot;">​</a></h5><p>在 Java 虚拟机中，可以使用 -Xss 或 -XX:ThreadStackSize 参数来设置每个线程的栈大小。以下是两种常见的设置方式：</p><ol><li><strong>使用</strong> -Xss** 参数：** 将设置每个线程的栈大小为 512KB</li></ol><p>java -Xss512k test.java</p><ol><li><strong>使用</strong> -XX:ThreadStackSize** 参数：** 设置每个线程的栈大小为 1024 字节</li></ol><p>java -XX:ThreadStackSize=1024 YourJavaProgram</p><p>需要注意的是，这些参数的设置可能会受到具体的 JVM 实现和版本的影响，在实际应用中，通常不需要手动设置栈大小，Java 虚拟机会根据默认规则进行分配。</p><h5 id="执行会导致stack-over-flow的java-源代码文件" tabindex="-1">执行会导致Stack Over Flow的Java 源代码文件 <a class="header-anchor" href="#执行会导致stack-over-flow的java-源代码文件" aria-label="Permalink to &quot;执行会导致Stack Over Flow的Java 源代码文件&quot;">​</a></h5><h6 id="设置线程栈大小为256kb-复现stack-over-flow错误" tabindex="-1">设置线程栈大小为256kb，复现stack over flow错误 <a class="header-anchor" href="#设置线程栈大小为256kb-复现stack-over-flow错误" aria-label="Permalink to &quot;设置线程栈大小为256kb，复现stack over flow错误&quot;">​</a></h6><ul><li>一段Java代码：编写一个会导致 Stack Overflow 的 Java 代码如下：</li></ul><p>public class StackOverflowExample { private static int recursiveMethod(int value) { System.out.println(&quot;Depth: &quot; + value); return recursiveMethod(value + 1); } public static void main(String[] args) { try { // 设置较小的栈大小，例如 256KB System.out.println(&quot;Stack Overflow Example&quot;); System.out.println(&quot;----------------------&quot;); System.out.println(&quot;Initial depth: 1&quot;); System.out.println(&quot;----------------------&quot;); System.out.println(&quot;Setting stack size to 256KB&quot;); System.out.println(&quot;----------------------&quot;); // 使用 -Xss 参数设置栈大小 // 请注意，过小的栈大小可能导致 Stack Overflow 错误 // 在实际应用中，设置合适的栈大小是非常重要的 // 在正常情况下，不需要手动设置栈大小 System.out.println(&quot;Running recursiveMethod...&quot;); recursiveMethod(1); } catch (Throwable e) { System.out.println(&quot;----------------------&quot;); System.out.println(&quot;Caught: &quot; + e.getClass().getName()); System.out.println(&quot;Message: &quot; + e.getMessage()); } } }</p><p>在这个例子中，recursiveMethod 方法是一个递归方法，每次递归都会打印递归深度。在 main 方法中，我们尝试运行这个递归方法，并设置较小的栈大小。</p><ul><li>编译 Java 代码：在当前目录生成 StackOverflowExample.class 文件</li><li>编译 Java 源代码文件javac StackOverflowExample.java</li><li>运行 Java 代码并设置栈大小：</li><li>运行 Java 程序并设置栈大小为 64KBjava -Xss256k -cp . your/path/StackOverflowExample，-Xss256k 参数用于设置每个线程的栈大小为 256KB，上面的Java代码中会无限递归地创建recursiveMethod（），并且这个方法永远不会返回，指导JVM栈溢出，出现Stack Overflow 错误。</li></ul><h5 id="分析stack-overflow" tabindex="-1">分析Stack Overflow <a class="header-anchor" href="#分析stack-overflow" aria-label="Permalink to &quot;分析Stack Overflow&quot;">​</a></h5><p>在上面的示例代码操作中，mian线程的栈会不断的压入方法recursiveMethod的栈帧，由于该函数是无限递归的，所以永远不会被返回。因此，main线程中的栈帧永远不会被释放，知道栈帧占满虚拟机栈空间，导致Stack Overflow错误，上述操作的执行结果如下：</p><p>从上面的执行结果我们可以看出，栈的最大深度为1640，加上main方法的栈帧，main线程的栈中一共有1641个栈帧。而这段代码运行时的栈大小设置为了256 kb，单个栈帧的大小为 256*1024/1641 = 160 Bytes。 实际上，当Java方法中的局部变量增多之后，栈帧所占用的空间会逐渐增加，所以一般栈帧的大小在几百字节～几KB左右。而且栈帧也一般会随着方法的返回而自动地被JVM所卸载和释放。</p><h4 id="总结-1" tabindex="-1">总结 <a class="header-anchor" href="#总结-1" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>虚拟机栈是Java线程运行的时候存储运行方法的区域，一般每个Java线程都会有专属的虚拟机栈。虚拟机栈由很多栈帧构成，当一个方法执行的时候就会向虚拟机栈中压入一个栈帧，栈顶的栈帧就是当前的活动栈帧。</p><p>栈帧一般由局部变量表、操作数栈、动态连接和方法返回地址等构成，局部变量表主要存储方法所需要用到的局部变量；操作数栈则是将需要进行运算的操作数进行压栈和出栈操作；动态连接主要是在程序运行期间将常量池中的符号引用映射到真实的物理地址的操作，方便快速的访问栈帧对应方法的属性；方法返回地址则是调用方法的代码的物理内存地址。</p><h2 id="本地方法栈详解" tabindex="-1">本地方法栈详解 <a class="header-anchor" href="#本地方法栈详解" aria-label="Permalink to &quot;本地方法栈详解&quot;">​</a></h2><h3 id="java跨平台与jvm" tabindex="-1">Java跨平台与JVM <a class="header-anchor" href="#java跨平台与jvm" aria-label="Permalink to &quot;Java跨平台与JVM&quot;">​</a></h3><p>我们知道Java是一种跨平台的语言，也就是说同一段Java代码在所有的计算机平台上的运行表现都是一样的。一般的PC平台可以分为Window、Macos和Linux等，而移动端平台也分为IOS、Android，但是，Java代码在这些所有的平台上的运行表现都是一致的，这是怎么做到得呢？</p><p>实际上，Java本身是运行在虚拟机上的，而Java虚拟机（Java Virtual Machine，JVM）则是Oracle或者其它的HotSpot 厂商根据JVM标准开发的不同平台的虚拟机，从而将Java与平台解耦。JVM为我们屏蔽了平台的特性同时进行了抽象，使得Java代码可以一次编译处处运行。例如，我们在Java中创建一个线程只需要调用如下Java代码：</p><p>Thread thread = new Thread();</p><p>而实际上，不同平台创建线程的方式各不相同，其底层的操作系统也提供了不同的API来进行线程创建，如下：</p><p>window创建线程：</p><p>HANDLE hThread = CreateThread(NULL, 0, MyThreadFunction, NULL, 0, NULL);</p><p>linux创建线程:</p><p>pthread_t thread; int result = pthread_create(&amp;thread, NULL, MyThreadFunction, NULL);</p><p>可以看到，在linux平台上和window平台上创建线程的方法完全不同，而这些方法实际上是我们在这个平台上创建线程的唯一方法，是由操作系统提供的。因此，对于各个平台来说，运行的根本不是我们前面写的Java代码，而是这些系统系统的接口和方法。</p><p>我们的操作系统，无论是windows还是linux都是由C++代码书写而成的，因此，这些系统api一般都是C++的函数，所以我们后面说的native方法一般也就是c++方法。Java虚拟机的作用就是相当于一个包装层，去把这些Java代码翻译称为平台相关的代码或者二进制文件，然后给相应平台执行。</p><p>因此，Java只需要针对不同平台实现各自的满足要求的Java虚拟机，就可以实现一次编译处处运行。</p><h4 id="什么是本地方法" tabindex="-1">什么是本地方法？ <a class="header-anchor" href="#什么是本地方法" aria-label="Permalink to &quot;什么是本地方法？&quot;">​</a></h4><p>接着，我们就可以说说什么是Java的本地方法了。在Java中，本地方法（Native Method）是指由Java语言以外的语言编写的方法，这些方法的实现是由本地代码（通常是C或C++等语言编写的和平台相关的代码）编写的，并且可以通过Java本地接口（Java Native Interface，JNI）在Java程序中调用的方法。</p><p>Java的设计初衷是实现跨平台性，使得Java程序可以在不同的操作系统和硬件平台上运行。很多任务和方法都需要直接与底层系统交互，使用本地代码可以提高性能或者利用特定平台的功能。下面是使用本地方法的一般流程如下：</p><ol><li><strong>编写本地方法实现：</strong> 在本地代码中编写实现某个功能的方法。这通常是使用C或C++等语言完成的，这些C/C++语言编译成的代码通常跟特定平台相关。</li><li><strong>生成本地库：</strong> 将本地代码编译成共享库或动态链接库（如.dll、.so等），这称为本地库。</li><li><strong>声明本地方法：</strong> 在Java中声明一个本地方法，使用native关键字，并提供一个外部声明，告诉编译器该方法的实现在本地库中。</li><li><strong>使用JNI加载本地库：</strong> 在Java程序中使用JNI加载本地库，以便在运行时能够调用本地方法。</li><li><strong>调用本地方法：</strong> 在Java代码中调用本地方法，通过JNI桥接到本地库中的实现，从而完成与本地代码的交互。 例如，以下是一个简单的示例：</li></ol><p>public class NativeExample { // 在Java中声明本地方法 public native void callNativeMethod(); // 使用JNI加载本地库 static { System.loadLibrary(&quot;NativeLibrary&quot;); } public static void main(String[] args) { // 创建实例并调用本地方法 NativeExample example = new NativeExample(); example.callNativeMethod(); } }</p><p>在这个示例中，callNativeMethod方法是一个本地方法，它的实现在本地库中。System.loadLibrary(&quot;NativeLibrary&quot;);用于加载名为NativeLibrary的本地库。</p><p>需要注意的是，使用本地方法会降低Java程序的可移植性，并增加了与底层系统交互的复杂性。因此，通常建议在不是必要的情况下尽量避免使用本地方法，而选择纯Java实现。</p><h4 id="本地方法栈" tabindex="-1"><strong>本地方法栈</strong> <a class="header-anchor" href="#本地方法栈" aria-label="Permalink to &quot;**本地方法栈**&quot;">​</a></h4><p>前面介绍了什么是本地方法，即与平台、硬件相关的方法，一般使用C/C++语言实现，能够为Java跨平台功能提供支持。与此同时，Java代码本身为了提升某些模块的性能，也会通过JNI的方法去调用本地的C++方法等，这些C/ C++方法在编译之后，一般会被打成本地的.so或者.dll库来供Java代码使用。例如，一般的手机APP调用的美颜算法等，出于效率考虑，美颜算法就会使用C++实现SDK，然后给上层调用。</p><p>因此，Java的本地方法栈（Native Method Stack）就是专门用于管理本地方法的调用的栈，本地方法栈和Java虚拟机栈在内存结构上是分离的。本地方法栈通常包含本地方法的调用信息、局部变量以及用于操作数栈的相关信息，主要有以下特点：</p><ul><li>本地方法栈是线程私有的，每个线程都有自己的本地方法栈</li><li>本地方法的堆内存大小可以被实现为固定或可动态扩展的，一般C和C++代码的堆内存需要程序员手动进行管理</li><li>如果本地方法栈请求的栈容量超过了允许的最大值，将导致StackOverflowError异常</li><li>在动态扩展的情况下，如果尝试扩展栈时无法获得足够的内存，或者在创建新线程时无法分配足够的内存以创建对应的本地方法栈，将导致OutOfMemoryError异常 线程调用本地方法时，进入一个全新且不再受虚拟机限制的领域，拥有相同的权限。本地方法通过本地方法接口可以访问虚拟机内部的运行时数据区，具有直接使用本地处理器中的寄存器的能力，可以直接从本地内存的堆中分配任意数量的内存。</li></ul><h4 id="总结-2" tabindex="-1">总结 <a class="header-anchor" href="#总结-2" aria-label="Permalink to &quot;总结&quot;">​</a></h4><p>总而言之，为了跨平台Java针对不同的平台和硬件设备实现了相应的Java虚拟机，用来屏蔽相关平台的特性，使得Java代码能够一次编译处处运行。因此，Java线程本身就会调用很多的平台相关的方法，这些方法一般是使用C/C++等语言实现的。而本地方法栈就是这些本地方法的执行栈，每个线程都会有一个独立的本地方法栈，用来调用本地平台功能。</p><h2 id="jvm程序计数器" tabindex="-1">JVM程序计数器 <a class="header-anchor" href="#jvm程序计数器" aria-label="Permalink to &quot;JVM程序计数器&quot;">​</a></h2><h3 id="什么是程序计数器" tabindex="-1">什么是程序计数器？ <a class="header-anchor" href="#什么是程序计数器" aria-label="Permalink to &quot;什么是程序计数器？&quot;">​</a></h3><p><img src="'+v+'" alt="images/HHksbtsSgoQhQVx5tqIcyu9Nnag.png"></p><p>images/HHksbtsSgoQhQVx5tqIcyu9Nnag.png</p><h4 id="jvm读书的指头——程序计数器" tabindex="-1">JVM读书的指头——程序计数器 <a class="header-anchor" href="#jvm读书的指头——程序计数器" aria-label="Permalink to &quot;JVM读书的指头——程序计数器&quot;">​</a></h4><p>如果我们把字节码文件看作一本书的话，那么JVM的活儿其实很简单。就是照着字节码文件这本书一句一句去读，然后翻译给我们的CPU去执行。所以说JVM也有点儿像一个传达命令的翻译官，将Java源代码文件编译成的字节码文件翻译成各个硬件平台的指令，然后让计算机运行。</p><p>那么，不妨想想我们在读书的时候需要干些什么事情，需要有个桌子，草稿纸，书以及人。桌子就好比是计算机内存，Java字节码这本书只能放在内存里，为了提高读书效率，JVM还贴心的将内存分为堆、程序计数器、虚拟机栈、方法区和程序计数器。这些内存区域各有各的作用，但是我们今天重点需要介绍的是——程序计数器。</p><p>我们平时读书的时候习惯用手指着书，知道书读到哪一行了，有时候我们可能中途离开干其它事情、读其它书可能会有一个书签，记录当前读到的位置。JVM比我们更聪明一点儿，单独分配了一块儿内存区域叫做程序计数器，来充当手指作用的同时还能在上面记录下当前执行到的JVM 字节码的位置。这样以来在干完其它事的时候，能快速的从上次读过的地方继续开始。</p><p>这就是我们说的程序计数器的作用——记录字节码文件的执行位置。</p><h4 id="正经说说什么是程序计数器" tabindex="-1">正经说说什么是程序计数器 <a class="header-anchor" href="#正经说说什么是程序计数器" aria-label="Permalink to &quot;正经说说什么是程序计数器&quot;">​</a></h4><p>程序计数器也叫做程序寄存器（Program Counter Register），虽然它在JVM中是一块内存区域，但是其作用更类似于指令寄存器的作用，即会存储JVM需要执行的下一条指令。</p><p>在JVM中，程序计数器是线程私有的，每个线程都有自己独立的程序计数器，其生命周期与线程的生命周期保持一致。主要作用包括：</p><ol><li><strong>当前指令地址存储：</strong> 程序计数器存储的是当前线程正在执行的Java字节码指令的地址。由于Java是一种解释执行的语言，程序计数器的值被用来定位下一条即将执行的字节码指令。</li><li><strong>线程切换时的恢复点：</strong> 程序计数器在线程切换时起到重要作用。当一个线程被挂起，另一个线程被调度执行时，JVM会通过程序计数器来恢复被挂起线程的执行状态，确保程序能够从正确的位置继续执行。</li><li><strong>支持方法调用和返回：</strong> 在Java程序中，方法调用和返回都依赖于程序计数器。程序计数器保存方法调用的返回地址，以便方法执行完毕后能够正确返回到调用点。 程序计数器是JVM中唯一一个在多线程执行时不会发生线程安全问题的区域。这是因为每个线程有自己独立的程序计数器，不会被其他线程访问或修改。总体而言，JVM中的程序计数器在支持Java程序的运行时起到了关键的作用，它是实现线程切换和方法调用等功能的重要组成部分。</li></ol><h3 id="程序计数器执行流程" tabindex="-1">程序计数器执行流程 <a class="header-anchor" href="#程序计数器执行流程" aria-label="Permalink to &quot;程序计数器执行流程&quot;">​</a></h3><p><img src="'+m+'" alt="images/Yif7bNu0Yoc7GBxedIVctsYanfb.png"></p><p>images/Yif7bNu0Yoc7GBxedIVctsYanfb.png</p><p>如上图所示，当执行Java字节码时，程序计数器（Program Counter，PC）在JVM中起着关键的作用，它负责跟踪当前线程所执行的指令地址。简单来说，程序计数器会存储处于方法区当中Java字节码的指令，表示当前执行到的指令位置。JVM引擎会根据程序计数器的地址拿到指令的物理地址，并从局部变量表和操作数栈中拿到数据进行运算。</p><p>这里来尝试分析一段简单的Java代码：</p><p>public int add(int a, int b) { int result = a + b; return result; }</p><p>以下是上面Java代码对应的字节码文件以及其在JVM中的执行流程，强调了程序计数器在其中的作用：</p><p>stack=2, locals=4, args_size=3 0: iload_1 1: iload_2 2: iadd 3: istore_3 4: iload_3 5: ireturn</p><ol><li><strong>iload_1:</strong> 程序计数器记录下将执行的指令的地址偏移0。iload_1指令执行，将局部变量表中索引为1的局部变量（例如，整数变量 a）加载到操作数栈上。</li><li><strong>iload_2:</strong> 程序计数器更新为下一条指令的地址。iload_2指令执行，将局部变量表中索引为2的局部变量（例如，整数变量 b）加载到操作数栈上。</li><li><strong>iadd:</strong> 程序计数器继续更新。iadd指令执行，从操作数栈中弹出两个整数，相加并将结果推入操作数栈。</li><li><strong>istore_3:</strong> 程序计数器继续更新。istore_3指令执行，将操作数栈顶的整数值存储到局部变量表中索引为3的位置（例如，整数变量 result）。</li><li><strong>iload_3:</strong> 程序计数器再次更新。iload_3指令执行，将局部变量表中索引为3的局部变量的值加载到操作数栈上。</li><li><strong>ireturn:</strong> 程序计数器继续更新。ireturn指令执行，将结果作为方法的返回值，并结束方法的执行。 在整个执行过程中，程序计数器始终记录着当前线程即将执行的指令的地址。这保证了指令的有序执行，同时在方法调用、返回和异常处理等情况下，程序计数器都发挥了关键的作用。</li></ol><h3 id="总结-3" tabindex="-1">总结 <a class="header-anchor" href="#总结-3" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>程序计数器是Java虚拟机（JVM）中的一种寄存器，负责跟踪当前线程执行的字节码指令地址。它在Java程序的执行过程中发挥着关键作用，具体功能包括记录当前指令地址、支持线程切换时的恢复点、以及管理方法调用和返回过程。</p><p>在执行Java字节码时，程序计数器通过不断更新指向下一条即将执行的指令地址，保证指令有序地执行。每个线程都有自己独立的程序计数器，确保在多线程执行时不会发生线程安全问题。程序计数器在方法调用、返回和异常处理等情况下都发挥着关键的作用，确保程序能够正确执行。总之，程序计数器是JVM中重要的组成部分，为Java程序的顺利执行提供了必要的支持。</p><h2 id="堆" tabindex="-1">堆 <a class="header-anchor" href="#堆" aria-label="Permalink to &quot;堆&quot;">​</a></h2><h3 id="什么是堆" tabindex="-1">什么是堆？ <a class="header-anchor" href="#什么是堆" aria-label="Permalink to &quot;什么是堆？&quot;">​</a></h3><p>官方一点来说：Java堆内存（Java Heap）是Java虚拟机（JVM）中最大的一块内存区域之一，用于存储对象实例和数组，Java中的所有对象都在堆上分配内存。Java堆是线程共享的，所有线程都可以访问和操作堆上的对象。每个线程的局部变量表中存储的是对象引用，而实际的对象数据都存储在堆上。</p><p>假设我们是一个操作工人，每天都在操作台上用各种工具和原料来生产各种设备。那么，为了提升效率，一般我们的工作间和操作台的大小都是有限的，只会放少量的我们需要用的工具或者材料。但是，如果我们的工作是造一艘航母呢，需要大量的零件和工具，这些零件和工具不可能都放在我们的工作台上吧？所以，我们需要一个地方来存放大量的零件和工具 —— 仓库。那么我们该如何去仓库获取我们需要的零件和设备呢？最简单的方法是我们有一张表，上面记录了零件和设备在仓库的物理地址，当我们需要用到仓库中的零件和设备的时候，只需要根据这个地址去取就可以了。</p><p>在计算机中，操作台就像是CPU的内部寄存器，你作为那个操作工人就是ALU，而我们的仓库就是堆内存空间，可以帮助我们的程序存储大量的对象和数据。而仓库地址在计算机中就是引用或者说是指针，通过引用的方式来快速的获取对象和相关数据。所以说，堆实际上就是程序运行时存放对象或者数据的一个大仓库，为了解决Java虚拟机栈的上实时存储的数据量有限的问题，加快计算机的运行效率。</p><h3 id="堆内存oom-out-of-memory" tabindex="-1">堆内存OOM（Out Of Memory） <a class="header-anchor" href="#堆内存oom-out-of-memory" aria-label="Permalink to &quot;堆内存OOM（Out Of Memory）&quot;">​</a></h3><h4 id="什么是out-of-memory" tabindex="-1">什么是Out Of Memory？ <a class="header-anchor" href="#什么是out-of-memory" aria-label="Permalink to &quot;什么是Out Of Memory？&quot;">​</a></h4><p>就像现实世界的仓库大小是有限的一样，内存的堆大小也是有限的，当无法向仓库中存储新的零件和设备的时候，仓库肯定会告诉我们：“我已经满了，放不下新的东西了”。堆内存也一样，当堆内存满了之后，操作系统会抛出一个“Out Of Memory Error”来告诉程序员堆内存已经满了，你需要打扫仓库来腾出新的空间了。</p><p>无论在现实世界中“仓库满”了和在计算世界当中“堆满了”都是一件很严重的事情，在现实世界中如果仓库满了导致零件和设备放不进去，那么我们的工作人员也就没办法从仓库中拿到所需要的设备来进行工作，这样就会造成工期延误。而这个事情在计算机中会更加严重一点儿，如果真的出现OOM，程序在堆中无法分配新的对象就会造成程序的崩溃，是绝对需要避免的问题。</p><p>因此，在Java中，堆内存OOM（Out of Memory）指的是程序在运行过程中，无法再为新的对象分配足够的堆内存空间。这一般是因为程序运行时产生的对象太多，而垃圾回收无法及时释放不再使用的对象，最终导致堆内存溢出。下面是一些可能导致堆内存OOM的常见原因和解决方法：</p><p>上面这些问题就是常见的Java堆的Out Of Memory的原因，我们需要尽量避免这些问题来保证Java堆内存不会被耗尽。</p><h4 id="java代码模拟out-of-memory" tabindex="-1">Java代码模拟Out Of Memory <a class="header-anchor" href="#java代码模拟out-of-memory" aria-label="Permalink to &quot;Java代码模拟Out Of Memory&quot;">​</a></h4><p>下面是一个简单的Java代码来模拟Out Of Memory的现场，代码会不断地向list中添加1MB大小的字节数组，直到堆内存溢出，触发OutOfMemoryError。</p><p>import java.util.ArrayList; import java.util.List; public class OutOfMemoryExample { public static void main(String[] args) { List list = new ArrayList&lt;&gt;(); try { while (true) { list.add(new byte[1024 * 1024]); // 每次添加1兆的字节数组 } } catch (OutOfMemoryError e) { System.out.println(&quot;Caught OutOfMemoryError: &quot; + e.getMessage()); } } }</p><p>编译：</p><p>javac OutOfMemoryExample.java</p><p>运行：</p><p>java -Xmx128m OutOfMemoryExample</p><p>为了Out Of Memory错误更加容易复现，这里将整堆空间大小设置为了128MB，因此，最多循环128次Java堆内存就会发生溢出。</p><h4 id="如何解决out-of-memory" tabindex="-1">如何解决Out Of Memory <a class="header-anchor" href="#如何解决out-of-memory" aria-label="Permalink to &quot;如何解决Out Of Memory&quot;">​</a></h4><p>那么如何解决Out Of Memory呢？对于仓库来说，其实办法无非两个：1. 及时清理不再需要的东西 2. 扩大仓库的空间。</p><p>首先，我们得及时的清理掉仓库里面已经不被需要的设备，这也就是Java中的垃圾回收的概念。Java HotSpot设计了各种各样的垃圾回收器来帮助我们在堆空间分配满之前清理掉不需要的对象，这个我们在后面的内容中再详细去说</p><p>其次，我们也可以通过设置更大的Java堆内存空间来避免OOM，当然这只是一种治标不治本的办法。</p><p>除此之外，我们还需要通过一些工具来观察和发现已经出现了OOM的程序。总的来说，以下是一些常见的OOM的解决方法：</p><p>上面这些方法可以帮助诊断和解决Java应用程序中的内存问题，根据具体情况，可能需要综合使用这些方法来获得最佳效果。</p><h3 id="java堆内存泄漏" tabindex="-1">Java堆内存泄漏 <a class="header-anchor" href="#java堆内存泄漏" aria-label="Permalink to &quot;Java堆内存泄漏&quot;">​</a></h3><p>在仓库的类比当中，我们的操作员需要通过一个表来查询设备和实际仓库的地址，我们把这个地址叫做指针或者引用。实际上，当我们的仓库管理员希望清理仓库的时候，也需要根据这个表来判断哪些设备还有用需要保留下来，哪些设备已经没用了，需要当成垃圾移出仓库。</p><p>而内存泄漏说的就是这么样一种情况，实际上这个对象已经没有用了，但是它的位置信息没有从表中删除，也就导致管理员在清扫垃圾的时候不会去清扫这一部分对象。长此以往，整个堆内存就会被这种实际已经没用，但是还没从表中删除的对象所占满，导致OOM。</p><p>官方一点：堆内存泄漏通常发生在程序中保持对对象引用，但这些对象不再被程序所需要时未被正确释放的情况，下面是一些可能导致堆内存泄漏的情况，我们通过 Java 代码进行说明：</p><ol><li><strong>集合对象未释放：</strong></li></ol><p>import java.util.ArrayList; import java.util.List; public class HeapMemoryLeakExample { private static List objectList = new ArrayList&lt;&gt;(); public static void main(String[] args) { for (int i = 0; i listeners = new ArrayList&lt;&gt;(); public static void main(String[] args) { HeapMemoryLeakExample example = new HeapMemoryLeakExample(); example.setupListeners(); // 在程序的其他部分可能未正确移除监听器 // 这可能导致堆内存泄漏 } private void setupListeners() { for (int i = 0; i objectCache = new HashMap&lt;&gt;(); public static void main(String[] args) { // 缓存对象 cacheObjects(); // 在程序的其他部分可能未正确清理缓存 // 这可能导致堆内存泄漏 } private static void cacheObjects() { for (int i = 0; i &lt; 1000; i++) { MyObject myObject = new MyObject(); objectCache.put(&quot;key&quot; + i, myObject); } } private static class MyObject { // 一些数据和逻辑 } }</p><p>在这个例子中，对象被缓存在 objectCache 中，但如果在程序的其他部分没有正确清理缓存，可能导致堆内存泄漏。</p><h3 id="总结-4" tabindex="-1">总结 <a class="header-anchor" href="#总结-4" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>Java中的堆内存我们可以看作一个大的仓库，用来存放程序运行当中所需要的大量的数据和对象，这些数据和对象通过一个表格来记录它们在仓库中的实际地址，这个地址就是“引用”或者“指针”。</p><p>和仓库一样，堆内存也可能被占满，导致新分配的对象无法在堆中分配内存，从而导致程序错误，即Out Of Memory。垃圾回收器则是在仓库中不断的去发现和清扫哪些不再被需要的堆空间，以方便程序后续继续分配新的对象到仓库中。</p><p>有那么一些对象，其地址还被记录在引用表格当中，但是其实际上已经没有被程序所使用了，这就造成了所谓的“内存泄漏”，在Java代码中需要尽量避免可能造成堆内存泄漏的情况。</p><p>总之，这里我们简单介绍了下什么是堆、堆内存溢出和内存泄漏的相关内容，更多的关于堆内存的分代模型和垃圾回收器，可以参考后续的内容。</p>',242)])])}const y=t(J,[["render",b]]);export{S as __pageData,y as default};
